const body = $input.first().json.body;
const toolCall = body.message.toolCalls[0];
const args = toolCall.function["arguments"];
const parsed = typeof args === "string" ? JSON.parse(args) : args;
const nameParts = (parsed.name || '').trim().split(' ');

function normalizeTime(t) {
  if (!t) return '';
  t = String(t).trim();
  const upper = t.toUpperCase();
  const isPM = /PM/i.test(upper);
  const isAM = /AM/i.test(upper);
  const cleaned = t.replace(/\s*(AM|PM)\s*/gi, '').trim();
  const parts = cleaned.split(':');
  let h = parseInt(parts[0], 10);
  let m = parts[1] ? parseInt(parts[1], 10) : 0;
  if (isNaN(h)) return '';
  if (isNaN(m)) m = 0;
  const hasLeadingZero = parts[0].length === 2 && parts[0][0] === '0';
  if (isAM) {
    if (h === 12) h = 0;
  } else if (isPM) {
    if (h !== 12) h += 12;
  } else if (!hasLeadingZero && h >= 1 && h <= 9) {
    h += 12;
  }
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

function cleanPhone(p) {
  if (!p) return '';
  p = String(p).trim();
  const hasPlus = p.startsWith('+');
  const digits = p.replace(/\D/g, '');
  return hasPlus ? '+' + digits : digits;
}

return [{ json: { callId: toolCall.id, name: parsed.name || '', firstName: nameParts[0] || '', lastName: nameParts.slice(1).join(' ') || '', phone: cleanPhone(parsed.phone), service: parsed.service || 'Consultation', date: parsed.date || '', time: normalizeTime(parsed.time) } }];

const callId = $('Extract Book Params').first().json.callId;
const date = $('Extract Book Params').first().json.date;
const time = $('Extract Book Params').first().json.time;
const name = $('Extract Book Params').first().json.firstName;
return [{ json: { results: [{ toolCallId: callId, result: 'Done! ' + name + ', your appointment is confirmed for ' + date + ' at ' + time + '. See you then!' }] } }];

const body = $input.first().json.body;
const toolCall = body.message.toolCalls[0];
const args = toolCall.function["arguments"];
const parsed = typeof args === "string" ? JSON.parse(args) : args;
return [{ json: { callId: toolCall.id, date: parsed.date || '' } }];

const items = $input.all().map(i => i.json);
const callId = $('Extract Availability Params').first().json.callId;

let allSlots = [];
for (const data of items) {
  const keys = Object.keys(data).filter(k => k.match(/^\d{4}-\d{2}-\d{2}$/));
  for (const key of keys) {
    const dayData = data[key];
    if (dayData && dayData.slots) {
      allSlots = allSlots.concat(dayData.slots);
    }
  }
}

// Convert to PKT (UTC+5) and filter business hours 9AM-5PM
function toPKT(dt) {
  const d = new Date(dt);
  return new Date(d.getTime() + 5 * 60 * 60 * 1000);
}

function fmt(dt) {
  const pkt = toPKT(dt);
  let h = pkt.getUTCHours();
  const m = pkt.getUTCMinutes();
  const ap = h < 12 ? 'AM' : 'PM';
  if (h === 0) h = 12;
  else if (h > 12) h -= 12;
  return h + (m > 0 ? ':' + String(m).padStart(2,'0') : '') + ' ' + ap;
}

const filtered = allSlots.filter(s => {
  const h = toPKT(s).getUTCHours();
  return h >= 9 && h < 17;
});

const times = filtered.slice(0, 3).map(s => fmt(s));
let message;
if (times.length === 0) {
  message = 'That day looks fully booked. Would another day work for you?';
} else if (times.length === 1) {
  message = 'The only opening that day is ' + times[0] + '. Would that work?';
} else {
  message = 'I have a few openings that day — ' + times.slice(0,-1).join(', ') + ' or ' + times[times.length-1] + '. Which suits you best?';
}

return [{ json: { results: [{ toolCallId: callId, result: message }] } }];

