const body = $input.first().json.body;
const toolCall = body.message.toolCalls[0];
const args = toolCall.function["arguments"];
const parsed = typeof args === "string" ? JSON.parse(args) : args;

function normalizeTime(t) {
  if (!t) return '';
  t = String(t).trim();
  const upper = t.toUpperCase();
  const isPM = /PM/i.test(upper);
  const isAM = /AM/i.test(upper);
  const cleaned = t.replace(/\s*(AM|PM)\s*/gi, '').trim();
  const parts = cleaned.split(':');
  let h = parseInt(parts[0], 10);
  let m = parts[1] ? parseInt(parts[1], 10) : 0;
  if (isNaN(h)) return '';
  if (isNaN(m)) m = 0;
  // If already in 24hr format (has leading zero like 09 or h>=12) leave as-is
  const hasLeadingZero = parts[0].length === 2 && parts[0][0] === '0';
  if (isAM) {
    if (h === 12) h = 0;
  } else if (isPM) {
    if (h !== 12) h += 12;
  } else if (!hasLeadingZero && h >= 1 && h <= 9) {
    // Only ambiguous single-digit hours get PM treatment
    h += 12;
  }
  // If h >= 17 and no explicit PM was given, likely wrong - cap at business hours
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

return [{ json: { callId: toolCall.id, name: parsed.name || '', phone: parsed.phone || '', newDate: parsed.newDate || parsed.date || '', newTime: normalizeTime(parsed.newTime || parsed.time || '') } }];

const callId = $('Extract Reschedule Params').first().json.callId;
